    def _column_exists(self, cursor, table_name: str, column_name: str) -> bool:
        """Check if a column exists on a table via information_schema."""
        cursor.execute(
            'SELECT 1 FROM information_schema.columns '
            'WHERE table_schema = current_schema() '
            'AND table_name = %s AND column_name = %s',
            (table_name, column_name),
        )
        return cursor.fetchone() is not None


    def _migrate_mcp_admission_064(self, cursor):
        """Add the repeat-safe MCP child class to existing 060 graphs.

            Rollback is operational: disable ``FF_MCP_SERVER`` and recreate the
            container. The additive idle class/slots may remain without changing
            any other workload; rows are not removed while operations may refer to
            them.
            """
        cursor.execute("SELECT to_regclass('operation_admission_class') AS relation_name")
        relation_row = cursor.fetchone()
        try:
            relation_name = relation_row['relation_name']
        except (KeyError, TypeError):
            relation_name = relation_row[0]
        if relation_name is None:
            return
        cursor.execute('\n            ALTER TABLE operation_admission_class\n            DROP CONSTRAINT IF EXISTS operation_admission_class_name_check\n        ')
        cursor.execute("\n            ALTER TABLE operation_admission_class\n            ADD CONSTRAINT operation_admission_class_name_check CHECK (\n                class_name IN (\n                    'global', 'interactive', 'voice_interactive', 'mcp',\n                    'background', 'scheduled', 'maintenance', 'system'\n                )\n            )\n        ")
        cursor.execute("\n            INSERT INTO operation_admission_class (\n                class_name, parent_class_name, active_limit, queue_limit,\n                max_wait_ms, config_revision\n            ) VALUES ('mcp', 'global', 8, 32, 5000, '064-defaults')\n            ON CONFLICT (class_name) DO NOTHING\n        ")
        cursor.execute("\n            INSERT INTO operation_admission_slot (class_name, slot_number)\n            SELECT 'mcp', generate_series(1, 8)\n            ON CONFLICT (class_name, slot_number) DO NOTHING\n        ")


    def _migrate_conversational_voice_065(self, cursor):
        """Install the repeat-safe feature-065 voice coordination schema.

            The 065 delta is called only after the complete 064 migration chain.
            Rollback is operational: disable voice, drain media, and leave these
            additive tables and columns in place for older application code to
            ignore. A failed transaction is retried from the unchanged revision
            marker; destructive retirement requires a later reviewed revision.
            """
        cursor.execute("\n            SELECT\n                to_regclass('operation_admission_class') AS admission_class,\n                to_regclass('operation_admission_slot') AS admission_slot,\n                to_regclass('operation_record') AS operation_record,\n                to_regclass('background_task') AS background_task,\n                to_regclass('conversation_commit') AS conversation_commit,\n                to_regclass('workspace_layout') AS workspace_layout,\n                to_regclass('messages') AS messages\n        ")
        prerequisites = cursor.fetchone()
